    assertTrue(isEqual(exchange.networkIdToCode(std::string("Tron"), std::string("TRX")), std::string("TRX")));
    //
    //
    // Case #3
    //
    //
    assertTrue(isEqual(exchange.networkIdToCode(std::string("Bitcoin")), std::string("BTC"))); // exclusive match
    assertTrue(isEqual(exchange.networkIdToCode(std::string("Brc_20")), std::string("BRC20"))); // exclusive match
    // with currencyCode
    assertTrue(isEqual(exchange.networkIdToCode(std::string("Bitcoin"), std::string("USDC")), std::string("BRC20")));
    assertTrue(isEqual(exchange.networkIdToCode(std::string("Bitcoin"), std::string("BTC")), std::string("BTC")));
    assertTrue(isEqual(exchange.networkIdToCode(std::string("Brc_20"), std::string("USDC")), std::string("BRC20")));
    assertTrue(isEqual(exchange.networkIdToCode(std::string("Brc_20"), std::string("BTC")), std::string("BTC")));
    //
    //
    // Case #4: unknown networkCode
